diff --git a/maven-build.xml b/maven-build.xml
index 93e81600..f77e8eba 100644
--- a/maven-build.xml
+++ b/maven-build.xml
@@ -68,10 +68,10 @@
            debug="true" 
            optimize="false" 
            deprecation="true" 
-           target="1.6" 
+           target="1.8" 
            verbose="false" 
            fork="false" 
-           source="1.6">
+           source="1.8">
       <src>
         <pathelement location="${maven.build.srcDir.0}"/>
       </src>
@@ -99,10 +99,10 @@
            debug="true" 
            optimize="false" 
            deprecation="true" 
-           target="1.6" 
+           target="1.8" 
            verbose="false" 
            fork="false" 
-           source="1.6">
+           source="1.8">
       <src>
         <pathelement location="${maven.build.testDir.0}"/>
       </src>
diff --git a/src/main/java/org/jsoup/nodes/Entities.java b/src/main/java/org/jsoup/nodes/Entities.java
index be73e321..040e0984 100644
--- a/src/main/java/org/jsoup/nodes/Entities.java
+++ b/src/main/java/org/jsoup/nodes/Entities.java
@@ -107,7 +107,9 @@ public class Entities {
         while (m.find()) {
             int charval = -1;
             String num = m.group(3);
+            boolean isNumeric = false;
             if (num != null) {
+                isNumeric = true;
                 try {
                     int base = m.group(2) != null ? 16 : 10;
                     charval = Integer.valueOf(num, base);
@@ -118,9 +120,14 @@ public class Entities {
                 if (full.containsKey(name))
                     charval = full.get(name);
             }
-            if (charval != -1 || charval > 0xFFFF) {
-                String c = Character.toString((char) charval);
-                m.appendReplacement(accum, Matcher.quoteReplacement(c));
+            if (charval != -1 && charval <= 0xFFFF) {
+                // For named entities without semicolon, only replace if it's in the base set
+                if (isNumeric || m.group(0).endsWith(";") || base.containsKey(m.group(1))) {
+                    String c = Character.toString((char) charval);
+                    m.appendReplacement(accum, Matcher.quoteReplacement(c));
+                } else {
+                    m.appendReplacement(accum, Matcher.quoteReplacement(m.group(0)));
+                }
             } else {
                 m.appendReplacement(accum, Matcher.quoteReplacement(m.group(0)));
             }
